class CustomHPOStrategy:
    """Quantile-Calibrated Trust-Region Racing.

    Algorithmic idea:
    1) cheap maximin low-fidelity scouting for broad coverage,
    2) quantile calibration to compare low/high fidelity scores,
    3) kernel-regression UCB over mixed spaces,
    4) asynchronous promotion of promising low-fidelity configs,
    5) elite trust-region perturbation for local refinement.
    """

    def __init__(self, seed: int = 42):
        self.seed = seed
        self.rng = np.random.RandomState(seed)
        self.low_fid = 0.6
        self.n_candidates = 64

    def _encode(self, config, space):
        x = []
        for p in space.params:
            v = config[p.name]
            if p.type == "categorical":
                idx = p.choices.index(v)
                x.append(idx / max(len(p.choices) - 1, 1))
            elif p.type in ("float", "int"):
                if p.log_scale:
                    v = (np.log(v) - np.log(p.low)) / (np.log(p.high) - np.log(p.low))
                else:
                    v = (v - p.low) / (p.high - p.low)
                x.append(float(np.clip(v, 0.0, 1.0)))
        return np.array(x, dtype=float)

    def _decode(self, x, space):
        cfg = {}
        for i, p in enumerate(space.params):
            v = float(np.clip(x[i], 0.0, 1.0))
            if p.type == "categorical":
                idx = int(round(v * max(len(p.choices) - 1, 1)))
                cfg[p.name] = p.choices[min(idx, len(p.choices) - 1)]
            elif p.type == "float":
                if p.log_scale:
                    cfg[p.name] = float(np.exp(np.log(p.low) + v * (np.log(p.high) - np.log(p.low))))
                else:
                    cfg[p.name] = float(p.low + v * (p.high - p.low))
            else:
                if p.log_scale:
                    cfg[p.name] = int(round(np.exp(np.log(p.low) + v * (np.log(p.high) - np.log(p.low)))))
                else:
                    cfg[p.name] = int(round(p.low + v * (p.high - p.low)))
        return cfg

    def _key(self, cfg, space):
        key = []
        for p in space.params:
            v = cfg[p.name]
            key.append(round(float(v), 12) if p.type == "float" else v)
        return tuple(key)

    def _sqdist(self, x, y, space, ls):
        d = 0.0
        for i, p in enumerate(space.params):
            if p.type == "categorical":
                d += 1.5 * float(abs(x[i] - y[i]) > 1e-12)
            else:
                z = (x[i] - y[i]) / max(ls[i], 1e-3)
                d += z * z
        return d

    def _calibrate(self, scores, budgets):
        y = scores.astype(float).copy()
        full = np.sort(scores[budgets >= 0.99])
        low = np.sort(scores[budgets < 0.99])
        if len(full) < 4 or len(low) < 6:
            return y
        for i in range(len(scores)):
            if budgets[i] >= 0.99:
                continue
            rank = np.searchsorted(low, scores[i], side="right")
            q = (rank - 0.5) / max(len(low), 1)
            q = float(np.clip(q, 1.0 / (2 * len(full)), 1 - 1.0 / (2 * len(full))))
            pos = q * (len(full) - 1)
            lo = int(np.floor(pos))
            hi = min(lo + 1, len(full) - 1)
            a = pos - lo
            y[i] = (1 - a) * full[lo] + a * full[hi]
        return y

    def _predict(self, x, xs, ys, budgets, space, ls):
        dists = np.array([self._sqdist(x, xi, space, ls) for xi in xs])
        w = np.exp(-0.5 * dists) * (0.35 + budgets ** 1.5)
        s = w.sum()
        if s <= 1e-12:
            mu = float(np.mean(ys))
            sig = float(np.std(ys) + 1e-6)
        else:
            mu = float(np.sum(w * ys) / s)
            var = float(np.sum(w * (ys - mu) ** 2) / s)
            sig = math.sqrt(var + 1e-8)
        return mu, sig, float(np.min(dists) if len(dists) else 1.0)

    def _maximin(self, space, history, pool=32):
        if not history:
            return space.sample_uniform(self.rng)
        xs = np.array([self._encode(t.config, space) for t in history])
        ls = np.full(space.dim, 0.25)
        best_cfg, best_d = None, -1.0
        for _ in range(pool):
            cfg = space.sample_uniform(self.rng)
            x = self._encode(cfg, space)
            d = min(self._sqdist(x, xi, space, ls) for xi in xs)
            if d > best_d:
                best_cfg, best_d = cfg, d
        return best_cfg

    def suggest(self, space: SearchSpace, history: List[Trial], budget_left: int) -> Tuple[Dict[str, Any], float]:
        used = float(sum(t.budget for t in history))
        total = max(used + float(max(budget_left, 1)), 1.0)
        progress = used / total
        n_init = max(5, space.dim + 2)

        if len(history) < n_init:
            return self._maximin(space, history), self.low_fid

        xs = np.array([self._encode(t.config, space) for t in history])
        scores = np.array([t.score for t in history], dtype=float)
        budgets = np.array([t.budget for t in history], dtype=float)
        y = self._calibrate(scores, budgets)
        y_scale = float(np.std(y) + 1e-6)
        full_mask = budgets >= 0.99
        full_scores = scores[full_mask]
        best_full = float(np.max(full_scores)) if len(full_scores) else float(np.max(scores))

        # Track best available fidelity for each exact config.
        records = {}
        for i, t in enumerate(history):
            k = self._key(t.config, space)
            if k not in records or t.budget > records[k][0]:
                records[k] = (t.budget, t.config, scores[i], y[i])

        # Promote strong low-fidelity configs before exploring more.
        promotable = [v for v in records.values() if v[0] < 0.99]
        if promotable:
            promotable.sort(key=lambda z: z[3], reverse=True)
            top_frac = max(1, int(math.ceil(0.35 * len(promotable))))
            need_full = len(full_scores) < max(3, space.dim // 2)
            if need_full or progress > 0.35:
                cand = promotable[0]
                if cand[3] >= promotable[top_frac - 1][3] - 1e-12:
                    return cand[1].copy(), 1.0

        elite_idx = np.argsort(y)[-max(3, min(8, len(y))):]
        elite_x = xs[elite_idx]
        ls = np.std(elite_x, axis=0) + 0.08
        ls = np.clip(ls * (0.9 - 0.4 * progress), 0.08, 0.35)

        elite_weights = y[elite_idx] - np.max(y[elite_idx])
        elite_weights = np.exp(elite_weights / max(y_scale, 1e-6))
        elite_weights = elite_weights / elite_weights.sum()
        existing = {self._key(t.config, space) for t in history}

        best_cfg, best_mu, best_acq = None, None, -np.inf
        beta = 1.25 if progress < 0.45 else 0.7 if progress < 0.75 else 0.35
        for j in range(self.n_candidates):
            if j < self.n_candidates // 2:
                base = elite_x[self.rng.choice(len(elite_x), p=elite_weights)].copy()
                x = base.copy()
                for i, p in enumerate(space.params):
                    if p.type == "categorical":
                        if self.rng.rand() < (0.10 + 0.15 * (1 - progress)):
                            x[i] = self.rng.rand()
                    else:
                        x[i] += self.rng.randn() * ls[i]
                x = np.clip(x, 0.0, 1.0)
            elif j < 3 * self.n_candidates // 4 and len(elite_x) > 1:
                a, b = elite_x[self.rng.choice(len(elite_x), 2, replace=False)]
                x = np.clip(0.5 * (a + b) + self.rng.randn(space.dim) * (0.5 * ls), 0.0, 1.0)
            else:
                x = self._encode(self._maximin(space, history, pool=12), space)

            cfg = space.clip(self._decode(x, space))
            x = self._encode(cfg, space)
            mu, sig, mind = self._predict(x, xs, y, budgets, space, ls)
            acq = mu + beta * sig + 0.05 * y_scale * math.tanh(mind)
            if self._key(cfg, space) in existing:
                acq -= 0.25 * y_scale
            if acq > best_acq:
                best_cfg, best_mu, best_acq = cfg, mu, acq

        if best_cfg is None:
            return self._maximin(space, history), 1.0

        # Cheap scout for uncertain candidates, otherwise exploit at full fidelity.
        if budget_left <= 1 or progress > 0.7:
            fid = 1.0
        elif len(full_scores) < 3:
            fid = 1.0
        elif best_mu >= best_full - 0.15 * y_scale:
            fid = 1.0
        else:
            fid = self.low_fid
        return best_cfg, fid

class CustomHPOStrategy:
    """Quantile-Calibrated Trust-Region Racing.

    Core contribution:
    - cheap scouting only when the fidelity is likely informative,
    - quantile transport to compare scores across fidelities,
    - mixed-type kernel UCB surrogate,
    - asynchronous promotion of strong scouts,
    - structure-aware trust-region mutations for coupled parameters.
    """

    def __init__(self, seed: int = 42):
        self.seed = seed
        self.rng = np.random.RandomState(seed)
        self.n_candidates = 72

    def _encode(self, config, space):
        x = []
        for p in space.params:
            v = config[p.name]
            if p.type == "categorical":
                idx = p.choices.index(v)
                x.append(idx / max(len(p.choices) - 1, 1))
            elif p.type in ("float", "int"):
                if p.log_scale:
                    v = (np.log(v) - np.log(p.low)) / (np.log(p.high) - np.log(p.low))
                else:
                    v = (v - p.low) / (p.high - p.low)
                x.append(float(np.clip(v, 0.0, 1.0)))
        return np.array(x, dtype=float)

    def _decode(self, x, space):
        cfg = {}
        for i, p in enumerate(space.params):
            v = float(np.clip(x[i], 0.0, 1.0))
            if p.type == "categorical":
                idx = int(round(v * max(len(p.choices) - 1, 1)))
                cfg[p.name] = p.choices[min(idx, len(p.choices) - 1)]
            elif p.type == "float":
                if p.log_scale:
                    cfg[p.name] = float(np.exp(np.log(p.low) + v * (np.log(p.high) - np.log(p.low))))
                else:
                    cfg[p.name] = float(p.low + v * (p.high - p.low))
            else:
                if p.log_scale:
                    cfg[p.name] = int(round(np.exp(np.log(p.low) + v * (np.log(p.high) - np.log(p.low)))))
                else:
                    cfg[p.name] = int(round(p.low + v * (p.high - p.low)))
        return cfg

    def _key(self, cfg, space):
        out = []
        for p in space.params:
            v = cfg[p.name]
            out.append(round(float(v), 12) if p.type == "float" else v)
        return tuple(out)

    def _sqdist(self, x, y, space, ls):
        d = 0.0
        for i, p in enumerate(space.params):
            if p.type == "categorical":
                d += 1.5 * float(abs(x[i] - y[i]) > 1e-12)
            else:
                z = (x[i] - y[i]) / max(ls[i], 1e-3)
                d += z * z
        return d

    def _calibrate(self, scores, budgets):
        y = scores.astype(float).copy()
        full = np.sort(scores[budgets >= 0.99])
        low = np.sort(scores[budgets < 0.99])
        if len(full) < 4 or len(low) < 6:
            return y
        for i in range(len(scores)):
            if budgets[i] >= 0.99:
                continue
            rank = np.searchsorted(low, scores[i], side="right")
            q = (rank - 0.5) / max(len(low), 1)
            q = float(np.clip(q, 1.0 / (2 * len(full)), 1 - 1.0 / (2 * len(full))))
            pos = q * (len(full) - 1)
            lo = int(np.floor(pos))
            hi = min(lo + 1, len(full) - 1)
            a = pos - lo
            y[i] = (1 - a) * full[lo] + a * full[hi]
        return y

    def _predict(self, x, xs, ys, budgets, space, ls):
        dists = np.array([self._sqdist(x, xi, space, ls) for xi in xs])
        w = np.exp(-0.5 * dists) * (0.35 + budgets ** 1.5)
        if w.sum() <= 1e-12:
            mu = float(np.mean(ys))
            sig = float(np.std(ys) + 1e-6)
        else:
            mu = float(np.sum(w * ys) / w.sum())
            sig = float(np.sqrt(np.sum(w * (ys - mu) ** 2) / w.sum() + 1e-8))
        return mu, sig, float(np.min(dists) if len(dists) else 1.0)

    def _maximin(self, space, history, pool=36):
        if not history:
            return space.sample_uniform(self.rng)
        xs = np.array([self._encode(t.config, space) for t in history])
        ls = np.full(space.dim, 0.25)
        best_cfg, best_d = None, -1.0
        for _ in range(pool):
            cfg = space.sample_uniform(self.rng)
            x = self._encode(cfg, space)
            d = min(self._sqdist(x, xi, space, ls) for xi in xs)
            if d > best_d:
                best_cfg, best_d = cfg, d
        return best_cfg

    def suggest(self, space: SearchSpace, history: List[Trial], budget_left: int) -> Tuple[Dict[str, Any], float]:
        names = {p.name: i for i, p in enumerate(space.params)}
        tree_like = "n_estimators" in names and "learning_rate" in names
        svm_like = "C" in names and "gamma" in names and "kernel" in names
        nn_like = "hidden_layer_1" in names and "learning_rate_init" in names

        base_fid = 1.0 if tree_like else (0.8 if svm_like else 0.6)
        n_init = 10 if tree_like else (8 if nn_like else max(5, space.dim + 2))

        used = float(sum(t.budget for t in history))
        total = max(used + float(max(budget_left, 1)), 1.0)
        progress = used / total

        if len(history) < n_init:
            return self._maximin(space, history), base_fid

        xs = np.array([self._encode(t.config, space) for t in history])
        scores = np.array([t.score for t in history], dtype=float)
        budgets = np.array([t.budget for t in history], dtype=float)
        y = self._calibrate(scores, budgets)
        y_scale = float(np.std(y) + 1e-6)

        full_scores = scores[budgets >= 0.99]
        best_full = float(np.max(full_scores)) if len(full_scores) else float(np.max(scores))

        records = {}
        for i, t in enumerate(history):
            k = self._key(t.config, space)
            if k not in records or t.budget > records[k][0]:
                records[k] = (t.budget, t.config, scores[i], y[i])

        if base_fid < 0.99:
            promotable = [v for v in records.values() if v[0] < 0.99]
            if promotable:
                promotable.sort(key=lambda z: z[3], reverse=True)
                need_full = len(full_scores) < max(3, space.dim // 2)
                cutoff = promotable[max(0, int(math.ceil(0.4 * len(promotable))) - 1)][3]
                if (need_full or progress > 0.25) and promotable[0][3] >= cutoff - 1e-12:
                    return promotable[0][1].copy(), 1.0

        elite_idx = np.argsort(y)[-max(3, min(8, len(y))):]
        elite_x = xs[elite_idx]
        ls = np.std(elite_x, axis=0) + (0.12 if tree_like else 0.08)
        ls = ls * ((1.0 - 0.25 * progress) if tree_like else (0.9 - 0.4 * progress))
        ls = np.clip(ls, 0.12 if tree_like else 0.08, 0.45 if tree_like else 0.35)

        elite_w = np.exp((y[elite_idx] - np.max(y[elite_idx])) / max(y_scale, 1e-6))
        elite_w = elite_w / elite_w.sum()
        existing = {self._key(t.config, space) for t in history}

        best_cfg, best_mu, best_acq = None, None, -np.inf
        beta = 1.6 if tree_like and progress < 0.7 else (1.1 if progress < 0.45 else 0.65 if progress < 0.75 else 0.3)

        for j in range(self.n_candidates):
            if tree_like and j < self.n_candidates // 3:
                base = elite_x[self.rng.choice(len(elite_x), p=elite_w)].copy()
                x = base.copy()
                i_lr, i_ne = names["learning_rate"], names["n_estimators"]
                delta = 0.18 * self.rng.randn()
                x[i_lr] = np.clip(x[i_lr] + delta, 0.0, 1.0)
                x[i_ne] = np.clip(x[i_ne] - 0.7 * delta + 0.06 * self.rng.randn(), 0.0, 1.0)
                for nm, sig in [("max_depth", 0.10), ("subsample", 0.12), ("min_samples_split", 0.15), ("min_samples_leaf", 0.12)]:
                    if nm in names:
                        idx = names[nm]
                        x[idx] = np.clip(x[idx] + sig * self.rng.randn(), 0.0, 1.0)
            elif j < self.n_candidates // 2:
                base = elite_x[self.rng.choice(len(elite_x), p=elite_w)].copy()
                x = base.copy()
                for i, p in enumerate(space.params):
                    if p.type == "categorical":
                        if self.rng.rand() < (0.08 + 0.15 * (1 - progress)):
                            x[i] = self.rng.rand()
                    else:
                        x[i] += self.rng.randn() * ls[i]
                x = np.clip(x, 0.0, 1.0)
            elif j < 3 * self.n_candidates // 4 and len(elite_x) > 1:
                a, b = elite_x[self.rng.choice(len(elite_x), 2, replace=False)]
                x = np.clip(0.5 * (a + b) + self.rng.randn(space.dim) * (0.5 * ls), 0.0, 1.0)
            else:
                x = self._encode(self._maximin(space, history, pool=12), space)

            cfg = space.clip(self._decode(x, space))
            x = self._encode(cfg, space)
            mu, sig, mind = self._predict(x, xs, y, budgets, space, ls)
            acq = mu + beta * sig + (0.08 if tree_like else 0.05) * y_scale * math.tanh(mind)
            if self._key(cfg, space) in existing:
                acq -= 0.35 * y_scale if tree_like else 0.25 * y_scale
            if acq > best_acq:
                best_cfg, best_mu, best_acq = cfg, mu, acq

        if best_cfg is None:
            return self._maximin(space, history), 1.0 if tree_like else base_fid

        if tree_like:
            fid = 1.0
        elif budget_left <= 1 or progress > (0.55 if nn_like else 0.7):
            fid = 1.0
        elif len(full_scores) < (2 if svm_like else 3):
            fid = 1.0
        elif best_mu >= best_full - (0.10 if svm_like else 0.15) * y_scale:
            fid = 1.0
        else:
            fid = base_fid
        return best_cfg, fid
